    /** Ready-to-print <svg> for an icon key; unknown keys fall back to the link icon. */
    public static function svg(string $key, int $size = 18): string
    {
        $size = max(8, min(64, $size));

        if (isset(self::BRAND[$key])) {
            return '<svg width="'.$size.'" height="'.$size.'" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false"><path d="'.self::BRAND[$key].'"/></svg>';
        }

        $inner = self::STROKE[$key] ?? self::STROKE['link'];

        return '<svg width="'.$size.'" height="'.$size.'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'.$inner.'</svg>';
    }

    /** Keys a custom link may choose from. */
    public static function customKeys(): array
    {
        return array_values(array_intersect(config('platform-settings.custom_icons', []), array_keys(self::STROKE)));
    }
}
